package vn.contractgovernance.api.privacy;
import java.util.*;
import java.sql.Timestamp;
import org.springframework.stereotype.Service;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;
import vn.contractgovernance.api.shared.*;
import vn.contractgovernance.api.files.*;
import static vn.contractgovernance.api.obligation.DutyEvidence.id;
@Service public class PrivacyService {
 public final PrivacyRecords records;private final EntityStore store;private final JsonSupport json;private final CommandExecutor commands;private final AuditService audit;private final ContractRegistry schemas;private final ListQueries lists;private final FileDispositions files;private final EvidenceAccess access;private final JobQueue jobs;private final DispositionLocks locks;
 public PrivacyService(PrivacyRecords records,CommandExecutor commands,AuditService audit,ContractRegistry schemas,ListQueries lists,FileDispositions files,EvidenceAccess access,JobQueue jobs,DispositionLocks locks){this.records=records;this.store=records.store;this.json=records.json;this.commands=commands;this.audit=audit;this.schemas=schemas;this.lists=lists;this.files=files;this.access=access;this.jobs=jobs;this.locks=locks;}
 public EntityStore.Entity require(UUID id,Actor a){return records.request(id,a);}
 public EntityStore.Entity lock(UUID id,Actor a){var preview=require(id,a);records.lockRecords(preview.body().path("recordIds"));return store.lock("DataRequest",id);}
 public JsonNode get(UUID id,Actor a){return project(require(id,a),records.current(a));}
 public JsonNode list(Map<String,String> query,Actor a){a=records.current(a);a.requireRole("MAKER","DATA_OFFICER","AUDITOR");var args=new ArrayList<Object>();args.add(a.id());args.add("{"+String.join(",",a.branchIds().stream().map(UUID::toString).sorted().toList())+"}");args.add(a.hasAnyRole("DATA_OFFICER","AUDITOR"));String scope="cg_privacy_record_scoped(e.id,?,?::uuid[],?)";final Actor actor=a;return lists.page("DataRequest",a,query,false,scope,args,b->{var entity=require(id(b,"id"),actor);return project(entity,actor);});}
 private void createAuth(JsonNode b,Actor a){a=records.current(a);a.requireRole("MAKER","DATA_OFFICER");a.requireBranch(id(b,"branchId"));var seen=new HashSet<UUID>();for(var item:b.path("recordIds")){var rid=UUID.fromString(item.asString());if(!seen.add(rid))throw ApiException.validation("/recordIds","Record không được trùng.");if(!Objects.equals(records.resolve(rid,a).branchId(),id(b,"branchId")))throw ApiException.of("NOT_FOUND","Record không cùng branch.");}}
 public ApiResult create(JsonNode input,String key,Actor a){createAuth(input,a);return commands.execute(a,key,"POST","/api/v1/data-requests",input,null,()->createAuth(input,a),()->{records.lockRecords(input.path("recordIds"));createAuth(input,a);var b=(ObjectNode)json.nfc(input);b.put("createdAt",records.now()).put("updatedAt",records.now()).put("state","OPEN").put("requesterId",a.id().toString());for(String f:List.of("decision","decisionBasis","decisionBy","manifest","jobId"))b.putNull(f);for(String f:List.of("allowedActions","blockedActions","holdIds","holds"))b.set(f,json.array());b.set("contributorIds",json.array().add(a.id().toString()));UUID newId=UUID.randomUUID();var sources=records.contributors(new EntityStore.Entity("DataRequest",newId,id(input,"branchId"),1,b));if(sources.size()>50)throw ApiException.of("STATE_CONFLICT","Nguồn vượt giới hạn 50 contributors.");var allContributors=json.array();sources.forEach(v->allContributors.add(v.toString()));b.set("contributorIds",allContributors);var entity=store.create("DataRequest",newId,id(input,"branchId"),b);schemas.validateSchema("DataRequest",entity.body());event(entity,"SOURCE",input,a);audit.record(a,"CREATE",entity,null);return ApiResult.created(project(entity,a),"/api/v1/data-requests/"+entity.id());});}
 public void authorize(UUID id,String action,Actor a){var r=require(id,a);a=records.current(a);a.requireRole("DATA_OFFICER");if(!action.equals("PLACE_HOLD")){if(r.body().path("requesterId").asString().equals(a.id().toString()))throw ApiException.of("SOD_VIOLATION","Không tự review/execute data request.");for(var v:records.contributors(r))if(v.equals(a.id()))throw ApiException.of("SOD_VIOLATION","Officer phải độc lập với source/copy contributor.");}}
 public ApiResult command(UUID id,JsonNode input,String tag,String key,Actor a){JsonNode r=json.nfc(input);String action=r.path("action").asString();authorize(id,action,a);ETags.require(tag);return commands.execute(a,key,"POST","/api/v1/data-requests/"+id+"/commands",r,tag,()->authorize(id,action,a),()->{var request=lock(id,a);authorize(id,action,a);ETags.check(tag,request.version());var b=(ObjectNode)request.body().deepCopy();var stableContributors=records.contributors(request);if(stableContributors.size()>50)throw ApiException.of("STATE_CONFLICT","Nguồn vượt giới hạn 50 contributors.");var contributors=json.array();stableContributors.forEach(v->contributors.add(v.toString()));b.set("contributorIds",contributors);switch(action){
 case "START_REVIEW"->{state(b,"OPEN");b.put("state","IN_REVIEW");event(request,action,r,a);}
 case "REJECT"->{state(b,"OPEN","IN_REVIEW");b.put("state","REJECTED");event(request,action,r,a);}
 case "DECIDE"->{state(b,"IN_REVIEW");boolean actionable=Set.of("ALLOW","PARTIAL").contains(r.path("decision").asString());JsonNode proof=json.array();if(actionable){if(!r.hasNonNull("manifest"))throw ApiException.validation("/manifest","ALLOW/PARTIAL cần exact finite manifest.");proof=validateManifest(request,r.path("manifest"),a,true);if(r.path("decision").asString().equals("ALLOW")&&r.path("manifest").path("records").size()!=b.path("recordIds").size())throw ApiException.validation("/manifest/records","ALLOW cần đủ requested records; subset dùng PARTIAL.");}else if(r.hasNonNull("manifest"))throw ApiException.validation("/manifest","DEFER/REFUSE không có executable manifest.");var frozen=json.object();frozen.set("request",json.nfc(r));frozen.set("proof",proof);event(request,"DECISION",frozen,a);b.put("state","DECIDED").put("decision",r.path("decision").asString()).put("decisionBasis",r.path("basis").asString()).put("decisionBy",a.id().toString());b.set("manifest",r.path("manifest"));}
 case "EXECUTE"->{executionGuard(request,r.path("manifestHash").asString(),exactVersion(r.path("manifestVersion")),a,false);var frozen=decision(request);var manifest=b.path("manifest");reserve(request,manifest,frozen.path("proof"));UUID job=jobs.enqueue("DATA_DISPOSITION","DATA_REQUEST",id,request.branchId(),exactVersion(manifest.path("version")),manifest.path("hash").asString(),"DATA_DISPOSITION:"+id+":"+manifest.path("hash").asString(),json.object().put("officerId",a.id().toString()).put("manifestHash",manifest.path("hash").asString()),AuditService.traceId());b.put("jobId",job.toString());event(request,"EXECUTE_INTENT",r,a);}
 case "PLACE_HOLD"->{if(store.jdbc().queryForObject("select count(distinct h.id) from cg_record_hold h join cg_record_hold_member m on m.hold_id=h.id where m.record_id=any(?::uuid[])",Long.class,"{"+String.join(",",java.util.stream.StreamSupport.stream(b.path("recordIds").spliterator(),false).map(JsonNode::asString).toList())+"}")>=100)throw ApiException.of("STATE_CONFLICT","Hold history has reached 100 entries.");var selected=new HashSet<UUID>();b.path("recordIds").forEach(v->selected.add(UUID.fromString(v.asString())));var seen=new HashSet<UUID>();for(var v:r.path("recordIds")){UUID record=UUID.fromString(v.asString());if(!seen.add(record)||!selected.contains(record))throw ApiException.validation("/recordIds","Hold cần unique requested record subset.");records.available(record);}holdEvidence(request,r.path("basisFileIds"),a,true);var hold=(ObjectNode)r.deepCopy();hold.remove("action");hold.remove("basisFileIds");UUID holdId=UUID.randomUUID();hold.put("id",holdId.toString()).put("placedBy",a.id().toString()).put("placedAt",records.now()).putNull("releasedBy").putNull("releasedAt");hold.set("basisFileIds",r.path("basisFileIds"));schemas.validateSchema("LegalHold",hold);store.jdbc().update("insert into cg_record_hold(id,request_id,body,placed_by,created_at) values(?,?,?::jsonb,?,?)",holdId,id,json.stringify(hold),a.id(),Timestamp.from(records.clock.instant()));for(var record:seen)store.jdbc().update("insert into cg_record_hold_member(hold_id,record_id) values(?,?)",holdId,record);event(request,action,hold,a);}
 case "RELEASE_HOLD"->{var holds=store.jdbc().query("select body::text,placed_by,released_at from cg_record_hold where id=? for update",(rs,n)->List.of(rs.getString(1),rs.getObject(2,UUID.class).toString(),rs.getTimestamp(3)==null?"":rs.getTimestamp(3).toString()),id(r,"holdId"));if(holds.size()!=1)throw ApiException.of("NOT_FOUND","Hold không tồn tại.");var row=holds.getFirst();var hold=(ObjectNode)json.parse(row.get(0));if(row.get(1).equals(a.id().toString()))throw ApiException.of("SOD_VIOLATION","Người release phải khác người đặt hold.");if(!row.get(2).isEmpty())throw ApiException.of("STATE_CONFLICT","Hold đã release.");var selected=new HashSet<String>();b.path("recordIds").forEach(v->selected.add(v.asString()));for(var v:hold.path("recordIds"))if(!selected.contains(v.asString()))throw ApiException.of("NOT_FOUND","Hold không thuộc requested scope.");holdEvidence(request,r.path("basisFileIds"),a,true);hold.put("releasedBy",a.id().toString()).put("releasedAt",records.now());store.jdbc().update("update cg_record_hold set body=?::jsonb,released_by=?,released_at=? where id=? and released_at is null",json.stringify(hold),a.id(),Timestamp.from(records.clock.instant()),id(r,"holdId"));var source=json.object();source.set("request",r);source.set("hold",hold);event(request,action,source,a);}
 default->throw ApiException.validation("/action","Unsupported privacy command.");}b.put("updatedAt",records.now());var updated=store.update(request,b);schemas.validateSchema("DataRequest",updated.body());audit.record(a,action,updated,r.path("reason").asString());return ApiResult.ok(project(updated,a));});}
 public JsonNode validateManifest(EntityStore.Entity request,JsonNode manifest,Actor officer,boolean mutation){exactVersion(manifest.path("version"));var canonical=(ObjectNode)json.nfc(manifest);canonical.remove("hash");if(!json.hash(canonical).equals(manifest.path("hash").asString()))throw ApiException.validation("/manifest/hash","Manifest hash phải bind toàn payload bỏ hash.");if(!manifest.path("purpose").equals(request.body().path("purpose")))throw ApiException.validation("/manifest/purpose","Manifest purpose khác request.");var requested=new HashSet<String>();request.body().path("recordIds").forEach(v->requested.add(v.asString()));var seen=new HashSet<String>();var proofs=json.array();for(var record:manifest.path("records")){String rid=record.path("recordId").asString();if(!requested.contains(rid)||!seen.add(rid))throw ApiException.validation("/manifest/records","Manifest record phải unique requested subset.");String action=record.path("action").asString();String type=request.body().path("requestType").asString();if(type.equals("ACCESS")&&!action.equals("PROVIDE_REDACTED_COPY")||type.equals("CORRECTION")&&!action.equals("CORRECT_CURRENT_METADATA")||type.equals("ERASURE")&&!Set.of("REDACT","DELETE_BYTES").contains(action))throw ApiException.validation("/manifest/records/action","Action không phù hợp requestType.");if(record.hasNonNull("holdId")&&store.jdbc().queryForObject("select count(*) from cg_record_hold_member where hold_id=? and record_id=?",Long.class,id(record,"holdId"),UUID.fromString(rid))!=1L)throw ApiException.validation("/manifest/records/holdId","Hold reference không thuộc đúng record.");records.holds(UUID.fromString(rid));records.available(UUID.fromString(rid));proofs.add(records.proof(request,record,officer,mutation));}return proofs;}
 public static int exactVersion(JsonNode value){try{return new java.math.BigDecimal(value.asString()).toBigIntegerExact().intValueExact();}catch(RuntimeException invalid){throw ApiException.validation("/manifest/version","Version cannot match a real server version.");}}
 public boolean sameProof(JsonNode left,JsonNode right){if(left.isArray()&&right.isArray()){if(left.size()!=right.size())return false;for(int i=0;i<left.size();i++)if(!sameProof(left.get(i),right.get(i)))return false;return true;}var a=(ObjectNode)left.deepCopy();var b=(ObjectNode)right.deepCopy();if(a.has("retentionReview"))((ObjectNode)a.path("retentionReview")).remove("reviewEligible");if(b.has("retentionReview"))((ObjectNode)b.path("retentionReview")).remove("reviewEligible");return a.equals(b);}
 public JsonNode decision(EntityStore.Entity request){var row=store.jdbc().query("select body::text,body_hash from cg_privacy_event where request_id=? and kind='DECISION' order by ordinal desc limit 1",(rs,n)->{var b=json.parse(rs.getString(1));if(!json.hash(b).equals(rs.getString(2)))throw ApiException.of("STORAGE_INTEGRITY","Decision history hash mismatch.");return b;},request.id());if(row.size()!=1)throw ApiException.of("STATE_CONFLICT","Missing immutable privacy decision.");return row.getFirst();}
 public void executionGuard(EntityStore.Entity request,String hash,int version,Actor actor,boolean retry){authorize(request.id(),"EXECUTE",actor);state(request.body(),"DECIDED");records.currentGrants(request,actor);if(!Set.of("ALLOW","PARTIAL").contains(request.body().path("decision").asString())||!request.body().hasNonNull("manifest"))throw ApiException.of("STATE_CONFLICT","Decision không cho execute.");var manifest=request.body().path("manifest");var frozen=decision(request);if(!frozen.path("request").path("manifest").equals(manifest)||!manifest.path("hash").asString().equals(hash)||exactVersion(manifest.path("version"))!=version)throw ApiException.of("BASE_CONFLICT","Exact approved manifest required.");if(!retry){if(request.body().hasNonNull("jobId"))throw ApiException.of("DISPOSITION_COMMITTED","Disposition intent đã committed; retry exact existing Job.");if(!sameProof(validateManifest(request,manifest,actor,false),frozen.path("proof")))throw ApiException.of("BASE_CONFLICT","Reviewed record/copy/source proof changed.");}}
 private void reserve(EntityStore.Entity request,JsonNode manifest,JsonNode proofs){var recordsById=new TreeMap<String,JsonNode>();for(var record:manifest.path("records"))recordsById.put(record.path("recordId").asString(),record);for(var record:recordsById.values()){UUID rid=id(record,"recordId");records.holds(rid);records.available(rid);var proof=java.util.stream.StreamSupport.stream(proofs.spliterator(),false).filter(p->p.path("recordId").equals(record.path("recordId"))).findFirst().orElseThrow();if(record.path("action").asString().equals("DELETE_BYTES")){var file=proof.path("file");var keys=new TreeMap<String,String>();keys.put(file.path("key").asString(),file.path("hash").asString());if(file.hasNonNull("redactedKey"))keys.put(file.path("redactedKey").asString(),file.path("redactedHash").asString());for(var key:keys.keySet())locks.key(key);for(var entry:keys.entrySet()){var refs=store.jdbc().query("select file_id from cg_file_blob where storage_key=? or redacted_storage_key=?",(rs,n)->rs.getObject(1,UUID.class),entry.getKey(),entry.getKey());if(refs.stream().anyMatch(owner->!owner.equals(rid)))throw ApiException.of("READINESS_BLOCKED","Shared retained byte owner outside exact deletion record; no false erasure.");store.jdbc().update("insert into cg_disposition_key(storage_key,request_id,record_id,expected_hash) values(?,?,?,?)",entry.getKey(),request.id(),rid,entry.getValue());}}store.jdbc().update("insert into cg_disposition_record(request_id,record_id,action,expected_version,phase,proof,proof_hash) values(?,?,?,?,'RESERVED',?::jsonb,?)",request.id(),rid,record.path("action").asString(),exactVersion(record.path("expectedRecordVersion")),json.stringify(proof),json.hash(proof));}}
 private void holdEvidence(EntityStore.Entity request,JsonNode ids,Actor a,boolean attach){var seen=new HashSet<UUID>();for(var value:ids){UUID fileId=UUID.fromString(value.asString());if(!seen.add(fileId))throw ApiException.validation("/basisFileIds","Evidence IDs trùng.");var f=access.requireClean(fileId,"DATA_REQUEST",request.id(),request.branchId(),a);access.requireFull(f,a);files.proof(f);if(attach){store.jdbc().update("insert into cg_file_association(file_id,target_type,target_id,historical,created_at) values(?,'DATA_REQUEST',?,true,?) on conflict(file_id,target_type,target_id) do update set historical=true",fileId,request.id(),Timestamp.from(records.clock.instant()));if(!f.body().path("attached").asBoolean()){var b=(ObjectNode)f.body().deepCopy();b.put("attached",true).put("updatedAt",records.now());store.update(f,b);}}}}
 public void event(EntityStore.Entity request,String kind,JsonNode body,Actor actor){var normalized=json.nfc(body);store.jdbc().update("insert into cg_privacy_event(id,request_id,kind,body,body_hash,actor_id,recorded_at) values(?,?,?,?::jsonb,?,?,?)",UUID.randomUUID(),request.id(),kind,json.stringify(normalized),json.hash(normalized),actor.id(),Timestamp.from(records.clock.instant()));}
 public JsonNode project(EntityStore.Entity request,Actor a){var b=(ObjectNode)request.body().deepCopy();var holds=store.jdbc().query("select distinct h.id,h.body::text from cg_record_hold h join cg_record_hold_member m on m.hold_id=h.id where m.record_id=any(?::uuid[]) order by h.id limit 101",(rs,n)->json.parse(rs.getString(2)),"{"+String.join(",",java.util.stream.StreamSupport.stream(b.path("recordIds").spliterator(),false).map(JsonNode::asString).toList())+"}");if(holds.size()>100)throw ApiException.of("STATE_CONFLICT","Hold history exceeds closed response limit.");var full=json.array();var ids=json.array();for(var hold:holds){boolean visible=true;for(var member:hold.path("recordIds"))try{records.resolve(UUID.fromString(member.asString()),a);}catch(ApiException hidden){visible=false;break;}if(visible){full.add(hold);ids.add(hold.path("id").asString());}}b.set("holds",full);b.set("holdIds",ids);var actions=json.array();var blocked=json.array();var candidates=new ArrayList<String>(List.of("PLACE_HOLD","RELEASE_HOLD"));switch(b.path("state").asString()){case "OPEN"->candidates.addAll(List.of("START_REVIEW","REJECT"));case "IN_REVIEW"->candidates.addAll(List.of("REJECT","DECIDE"));case "DECIDED"->{if(Set.of("ALLOW","PARTIAL").contains(b.path("decision").asString())&&!b.hasNonNull("jobId"))candidates.add("EXECUTE");}default->{}}for(var action:candidates)try{authorize(request.id(),action,a);if(action.equals("EXECUTE"))executionGuard(request,b.path("manifest").path("hash").asString(),b.path("manifest").path("version").asInt(),a,false);if(action.equals("PLACE_HOLD"))for(var record:b.path("recordIds"))records.available(UUID.fromString(record.asString()));if(action.equals("RELEASE_HOLD")&&java.util.stream.StreamSupport.stream(full.spliterator(),false).noneMatch(h->!h.hasNonNull("releasedAt")&&!h.path("placedBy").asString().equals(a.id().toString())))continue;actions.add(action);}catch(ApiException ex){if(!a.hasRole("AUDITOR"))blocked.add(json.object().put("action",action).put("code",ex.code()).put("reason",ex.getMessage()));}if(a.hasRole("AUDITOR")&&!a.hasRole("DATA_OFFICER")&&!a.hasPermission("SENSITIVE_READ")){b.put("subjectReference","[REDACTED]").put("purpose","[REDACTED]");if(b.hasNonNull("decisionBasis"))b.put("decisionBasis","[REDACTED]");for(var h:full)((ObjectNode)h).put("reason","[REDACTED]");if(b.hasNonNull("manifest")){var m=(ObjectNode)b.path("manifest");m.put("purpose","[REDACTED]").put("basis","[REDACTED]");for(var record:m.path("records")){((ObjectNode)record).put("reason","[REDACTED]");if(record.hasNonNull("correction")){var c=(ObjectNode)record.path("correction");c.put("personName","[REDACTED]").put("roleLabel","[REDACTED]").put("email","redacted@example.invalid").put("phone","0000000000");}}}}b.set("allowedActions",actions);b.set("blockedActions",blocked);return b;}
 private void state(JsonNode n,String...states){if(!Set.of(states).contains(n.path("state").asString()))throw ApiException.of("STATE_CONFLICT","DataRequest state does not permit action.");}
}
